#!/usr/bin/env node
/**
 * Writes every SHIPPED client translation key into a plain data file the
 * server owns, so the API can seed Localization on boot (CLAUDE.md rule 38).
 *
 * Why a generated file rather than an import: `server/src` imports zero
 * `@duncit/*` packages by design (rule 40) — the Docker image never copies
 * them. The keys still have to reach the database, and the database is only
 * reachable FROM the server, so the copy travels as data instead.
 *
 * The server's own email keys are NOT here: it already ships those in
 * `email-i18n.ts` and the seeder reads them directly.
 *
 * Run `node scripts/generate-shipped-keys.mjs` after adding a key; the
 * `--check` flag fails instead of writing, which is what CI runs so a stale
 * file cannot ship.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { catalogueEntries } from "./lib/bundle-catalogue.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(
  ROOT,
  "server/src/modules/platform/localization/shipped-keys.ts",
);
const NAME = "generate-shipped-keys";
const check = process.argv.includes("--check");

const entries = catalogueEntries(ROOT);
/** Deduplicated: two bundles may ship the same key, and the first wins — the
 * same rule `allFallbackEntries()` applies on the client. */
const merged = new Map();
for (const entry of entries) {
  if (!merged.has(entry.key)) merged.set(entry.key, entry.value);
}
const sorted = [...merged].sort(([a], [b]) => a.localeCompare(b));

const body = sorted
  .map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`)
  .join("\n");

const file = `/**
 * GENERATED by \`node scripts/generate-shipped-keys.mjs\` — do not edit.
 *
 * Every key the client surfaces ship copy for, as flat \`key -> English text\`.
 * The server seeds these into Localization on boot so a fresh database (or a
 * newly deployed key) is translatable without anyone opening the admin panel.
 *
 * It is a generated FILE rather than an import because \`server/src\` takes no
 * \`@duncit/*\` dependency (rule 40) — the Docker image never copies those
 * packages, so the copy has to travel as data.
 */
export const SHIPPED_CLIENT_KEYS: Record<string, string> = {
${body}
};
`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: shipped-keys.ts is out of date (${sorted.length} key(s) in the bundles).\n` +
        "Run `node scripts/generate-shipped-keys.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(`${NAME}: shipped-keys.ts matches the bundles (${sorted.length} keys)`);
} else {
  writeFileSync(OUT, file, "utf8");
  console.log(`${NAME}: wrote ${sorted.length} key(s) to ${OUT.slice(ROOT.length + 1)}`);
}
